-- Lead Desk · AMC and "Generated by me" read rules that cannot be switched off by accident (10 Nov 2026)
-- Run once in Supabase → SQL Editor. Safe to run again. No leads are changed.
--
-- Why: the rule "who can read which lead" lived in one database policy that several older SQL files re-create
-- (09, 11, 12, 23). Running any of them after 24_amc_renewals.sql put back an older version of the rule without
-- the AMC part, so AMC users had the permission but still received no orders.
-- Now the two newer rules are separate policies of their own. The database allows a read when ANY policy allows
-- it, so re-running an older file can no longer remove them.

-- AMC: read won orders only (permission lead.view_won)
drop policy if exists leads_select_won on public.leads;
create policy leads_select_won on public.leads for select to authenticated
  using ((doc->>'deleted') is null and status = 'Won' and (select public.has_perm('lead.view_won')));

-- Sales: read (not edit) leads they generated themselves (permission lead.view_generated)
drop policy if exists leads_select_generated on public.leads;
create policy leads_select_generated on public.leads for select to authenticated
  using ((doc->>'deleted') is null and (select public.my_engineer()) <> '' and (select public.has_perm('lead.view_generated'))
         and lower(btrim(coalesce(doc->>'generatedBy',''))) = lower((select public.my_engineer())));

-- Check: three rows are expected: leads_select, leads_select_generated, leads_select_won
select policyname, left(qual, 110) as rule from pg_policies
where schemaname = 'public' and tablename = 'leads' and cmd = 'SELECT' order by 1;
